import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Cooperative tiled convolution with cross-filter shared-memory reuse:
// NCHW input (N,3,224,224), weight (96,3,11,11), bias (96), stride 4,
// padding 2, output (N,96,55,55). Each CTA computes one 12x12 output
// tile for ALL 96 filters of one image: the reusable 55x55x3 input
// window is staged into shared memory only ONCE per CTA (instead of
// once per filter), then the CTA loops over the 96 filters,
// cooperatively staging each 363-float filter into shared memory while
// each of the 144 threads accumulates one output element per filter
// from shared memory. This removes the 96x redundant global reloading
// of the input window that the per-filter CTA mapping caused.
.visible .entry conv2d_kernel(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_out
)
{
    .reg .b64 %rd_in, %rd_w, %rd_b, %rd_out, %rd_addr;
    .reg .b32 %r_tid, %r_tx, %r_ty, %r_bx, %r_by, %r_n;
    .reg .b32 %r_k, %r_oh0, %r_ow0, %r_oh, %r_ow;
    .reg .b32 %r_in_base, %r_wbase, %r_smin, %r_smw;
    .reg .b32 %r_idx, %r_c, %r_r, %r_col, %r_ih, %r_iw;
    .reg .b32 %r_t0, %r_t1, %r_kh, %r_kw, %r_row0, %r_col0, %r_soff;
    .reg .f32 %f_acc, %f_v, %f_w, %f_b;
    .reg .pred %p, %p1, %p2, %p_skip;
    // 55*55*3*4 = 36300 bytes input window, then 363*4 bytes of weights.
    .shared .align 16 .b8 smem[37752];
    ld.param.u64 %rd_in, [param_in];
    ld.param.u64 %rd_w, [param_w];
    ld.param.u64 %rd_b, [param_b];
    ld.param.u64 %rd_out, [param_out];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bx, %ctaid.x;
    mov.u32 %r_by, %ctaid.y;
    mov.u32 %r_n, %ctaid.z;
    // Thread -> output position inside the 12x12 tile.
    rem.u32 %r_tx, %r_tid, 12;
    div.u32 %r_ty, %r_tid, 12;
    // Tile origin in output coordinates.
    mul.lo.u32 %r_ow0, %r_bx, 12;
    mul.lo.u32 %r_oh0, %r_by, 12;
    // Shared memory bases.
    mov.u32 %r_smin, smem;
    add.u32 %r_smw, %r_smin, 36300;
    // Per-image input base element offset: n * 3 * 224 * 224.
    mul.lo.u32 %r_in_base, %r_n, 150528;
    // ---- Cooperative load of the 55x55x3 input window (zero-padded) ----
    mov.u32 %r_idx, %r_tid;
LOAD_IN_LOOP:
    setp.ge.u32 %p, %r_idx, 9075;
    @%p bra LOAD_IN_DONE;
    // idx -> (c, r, col) with r, col in [0,55)
    div.u32 %r_c, %r_idx, 3025;
    mul.lo.u32 %r_t0, %r_c, 3025;
    sub.u32 %r_t1, %r_idx, %r_t0;
    div.u32 %r_r, %r_t1, 55;
    mul.lo.u32 %r_t0, %r_r, 55;
    sub.u32 %r_col, %r_t1, %r_t0;
    // ih = oh0*4 + r - 2, iw = ow0*4 + col - 2 (unsigned wrap marks negatives)
    mul.lo.u32 %r_t0, %r_oh0, 4;
    add.u32 %r_t0, %r_t0, %r_r;
    sub.u32 %r_ih, %r_t0, 2;
    mul.lo.u32 %r_t0, %r_ow0, 4;
    add.u32 %r_t0, %r_t0, %r_col;
    sub.u32 %r_iw, %r_t0, 2;
    mov.f32 %f_v, 0f00000000;
    setp.ge.u32 %p1, %r_ih, 224;
    setp.ge.u32 %p2, %r_iw, 224;
    or.pred %p, %p1, %p2;
    @%p bra STORE_SM_IN;
    // offset = in_base + c*50176 + ih*224 + iw
    mul.lo.u32 %r_t0, %r_c, 50176;
    add.u32 %r_t0, %r_t0, %r_in_base;
    mul.lo.u32 %r_t1, %r_ih, 224;
    add.u32 %r_t0, %r_t0, %r_t1;
    add.u32 %r_t0, %r_t0, %r_iw;
    mul.wide.u32 %rd_addr, %r_t0, 4;
    add.u64 %rd_addr, %rd_addr, %rd_in;
    ld.global.f32 %f_v, [%rd_addr];
STORE_SM_IN:
    mul.lo.u32 %r_t0, %r_idx, 4;
    add.u32 %r_t0, %r_t0, %r_smin;
    st.shared.f32 [%r_t0], %f_v;
    add.u32 %r_idx, %r_idx, 144;
    bra LOAD_IN_LOOP;
LOAD_IN_DONE:
    bar.sync 0;
    // Output coordinates for this thread (fixed across the filter loop).
    add.u32 %r_oh, %r_oh0, %r_ty;
    add.u32 %r_ow, %r_ow0, %r_tx;
    setp.ge.u32 %p1, %r_oh, 55;
    setp.ge.u32 %p2, %r_ow, 55;
    or.pred %p_skip, %p1, %p2;
    // Sliding window origin inside the shared tile for this thread.
    mul.lo.u32 %r_row0, %r_ty, 4;
    mul.lo.u32 %r_col0, %r_tx, 4;
    // ---- Loop over all 96 filters, reusing the staged input window ----
    mov.u32 %r_k, 0;
LOOP_K:
    // Cooperative load of the 363 weights of filter k.
    mul.lo.u32 %r_wbase, %r_k, 363;
    mov.u32 %r_idx, %r_tid;
LOAD_W_LOOP:
    setp.ge.u32 %p, %r_idx, 363;
    @%p bra LOAD_W_DONE;
    add.u32 %r_t0, %r_wbase, %r_idx;
    mul.wide.u32 %rd_addr, %r_t0, 4;
    add.u64 %rd_addr, %rd_addr, %rd_w;
    ld.global.f32 %f_v, [%rd_addr];
    mul.lo.u32 %r_t0, %r_idx, 4;
    add.u32 %r_t0, %r_t0, %r_smw;
    st.shared.f32 [%r_t0], %f_v;
    add.u32 %r_idx, %r_idx, 144;
    bra LOAD_W_LOOP;
LOAD_W_DONE:
    bar.sync 0;
    @%p_skip bra COMPUTE_DONE;
    mov.f32 %f_acc, 0f00000000;
    mov.u32 %r_c, 0;
LOOP_C:
    mov.u32 %r_kh, 0;
LOOP_KH:
    mov.u32 %r_kw, 0;
LOOP_KW:
    // shared input offset = c*3025 + (row0+kh)*55 + col0+kw
    add.u32 %r_t0, %r_row0, %r_kh;
    mul.lo.u32 %r_t0, %r_t0, 55;
    add.u32 %r_t0, %r_t0, %r_col0;
    add.u32 %r_t0, %r_t0, %r_kw;
    mul.lo.u32 %r_t1, %r_c, 3025;
    add.u32 %r_soff, %r_t0, %r_t1;
    mul.lo.u32 %r_soff, %r_soff, 4;
    add.u32 %r_soff, %r_soff, %r_smin;
    ld.shared.f32 %f_v, [%r_soff];
    // shared weight offset = c*121 + kh*11 + kw
    mul.lo.u32 %r_t0, %r_c, 121;
    mul.lo.u32 %r_t1, %r_kh, 11;
    add.u32 %r_t0, %r_t0, %r_t1;
    add.u32 %r_t0, %r_t0, %r_kw;
    mul.lo.u32 %r_t0, %r_t0, 4;
    add.u32 %r_t0, %r_t0, %r_smw;
    ld.shared.f32 %f_w, [%r_t0];
    fma.rn.f32 %f_acc, %f_v, %f_w, %f_acc;
    add.u32 %r_kw, %r_kw, 1;
    setp.lt.u32 %p, %r_kw, 11;
    @%p bra LOOP_KW;
    add.u32 %r_kh, %r_kh, 1;
    setp.lt.u32 %p, %r_kh, 11;
    @%p bra LOOP_KH;
    add.u32 %r_c, %r_c, 1;
    setp.lt.u32 %p, %r_c, 3;
    @%p bra LOOP_C;
    // Add bias.
    mul.wide.u32 %rd_addr, %r_k, 4;
    add.u64 %rd_addr, %rd_addr, %rd_b;
    ld.global.f32 %f_b, [%rd_addr];
    add.f32 %f_acc, %f_acc, %f_b;
    // Store result: out element offset = ((n*96 + k)*55 + oh)*55 + ow
    mul.lo.u32 %r_t0, %r_n, 96;
    add.u32 %r_t0, %r_t0, %r_k;
    mul.lo.u32 %r_t0, %r_t0, 55;
    add.u32 %r_t0, %r_t0, %r_oh;
    mul.lo.u32 %r_t0, %r_t0, 55;
    add.u32 %r_t0, %r_t0, %r_ow;
    mul.wide.u32 %rd_addr, %r_t0, 4;
    add.u64 %rd_addr, %rd_addr, %rd_out;
    st.global.f32 [%rd_addr], %f_acc;
COMPUTE_DONE:
    // All threads must finish reading the shared filter weights before
    // the next iteration's cooperative load overwrites them.
    bar.sync 0;
    add.u32 %r_k, %r_k, 1;
    setp.lt.u32 %p, %r_k, 96;
    @%p bra LOOP_K;
    ret;
}
